        m_digits = []
        temp_m = m
        if temp_m == 0:
            m_digits = [0]
        else:
            while temp_m > 0:
                m_digits.append(temp_m % 7)
                temp_m //= 7
            m_digits.reverse()

        possible_b = list(set(m_digits))

        # n < m^2 and n = sum(a_i)
        # We know n_digits[0] is b_m, so n_digits has length <= m+1
        for n in range(1, m*m + 1):
            n_digits = []
            temp_n = n
            if temp_n == 0:
                n_digits = [0]
            else:
                while temp_n > 0:
                    n_digits.append(temp_n % 7)
                    temp_n //= 7
                n_digits.reverse()

            if len(n_digits) > m + 1:
                continue

            b = [0] * (m + 1)
            for j in range(len(n_digits)):
                b[m - j] = n_digits[j]

            all_b_in_m = True
            for i in range(m + 1):
                if b[i] not in m_digits:
                    all_b_in_m = False
                    break
            if not all_b_in_m:
                continue

            # Note: The problem says "the" digit b_i.
            # Let's check all possible sums of a_i.
            # For each i, a_i is removing b_i from m_digits.
            # If there are multiple occurrences of b_i, we need to check if any sum works.

            # Let's find all possible a_i for each b_i.
            a_options = []
