                for idx in range(len(m_digits_copy)):
                    if m_digits_copy[idx] == val_bi:
                        m_digits_copy.pop(idx)
                        # convert m_digits_copy back to a number
                        a_i = 0
                        for digit in m_digits_copy:
                            a_i = a_i * 7 + digit
                        opts.add(a_i)
                a_options.append(list(opts))

            # We need to check if there's a combination of a_i that sums to n.
            # This is a variation of the subset sum problem (or change making problem).
            # But we have m values, and each can be one of several options.
            # Since the number of options is small, we can use DP.

            dp = {0}
            for i in range(m):
                new_dp = set()
                for val in a_options[i]:
                    for prev_sum in dp:
                        new_dp.add(prev_sum + val)
                dp = new_dp

            if n in dp:
